<script lang="ts">
 import {onMount} from 'svelte';import {X,ArrowRight,Check,Plus,Paperclip,Upload,Download,CalendarDays,Layers,ShieldCheck} from '@lucide/svelte';
 import Badge from './Badge.svelte';import {api,upload,fmt,day} from './api';import type {Row,Dataset,FormSpec,Field} from './types';
 let {order,data,onclose,onform,onmutate}:{order:Row;data:Dataset;onclose:()=>void;onform:(s:FormSpec)=>void;onmutate:()=>Promise<void>}=$props();
 let dialog:HTMLDialogElement;let details:Row=$state({});let error=$state('');let busy=$state(false);let tab=$state('Overview');let uploadInput=$state<HTMLInputElement>(null!);
 const can=(g:string)=>data.user.grants.includes(g);
 const options=(list:Row[],label='name')=>list.map(r=>({value:r.id,label:r[label]}));
 onMount(()=>{dialog.showModal();return()=>dialog.close();});
 $effect(()=>{const id=order.id;const version=order.version;let valid=true;api(`/orders/${id}`).then(d=>{if(valid)details=d;}).catch(e=>{if(valid)error=e.message;});return()=>{valid=false;};});
 async function act(action:string,values:Row={}){await api(`/orders/${order.id}`,{action,version:order.version,...values});await onmutate();}
 function form(title:string,action:string,fields:Field[],submitLabel='Save record'){onform({title,description:order.po+' · '+order.style,fields,submitLabel,submit:v=>act(action,v)});}
 async function direct(action:string,values:Row={}){if(busy)return;error='';busy=true;try{await act(action,values);}catch(e){error=(e as Error).message;}finally{busy=false;}}
 const stageGrant:Record<string,string>={Development:'develop',Sampling:'sample',Planning:'plan',Cutting:'cut',Sewing:'sew',Finishing:'finish',Packing:'pack',Warehouse:'finance',Invoiced:'warehouse'};
 let workflowHint=$derived.by(()=>{if(order.approval==='Pending')return 'Waiting for order approval.';if(order.stage==='Planning')return order.line_id?'Allocation is set. Send this PO to CAD.':'Assign a sewing line, then send this PO to CAD.';if(['Development','Sampling'].includes(order.stage)){const required=order.stage==='Development'?['Style development','CAD / pattern']:['Pre-production sample'];const missing=required.filter(kind=>[...data.work_items].sort((a,b)=>b.id-a.id).find(w=>w.order_id===order.id&&w.kind===kind)?.status!=='Approved');return missing.length?'Approve '+missing.join(' and ')+' in the Development tab.':'Required approvals are complete. Ready for the next department.';}if(['Cutting','Sewing','Finishing','Packing'].includes(order.stage)){const remaining=order.quantity-(order.totals?.[order.stage]||0);return remaining>0?`Record ${fmt(remaining)} remaining good pieces, then complete a passing quality inspection.`:'Output is complete. A passing quality check after the latest output is required.';}return order.stage==='Warehouse'?'Finance must enter an invoice reference before dispatch.':order.stage==='Invoiced'?'Warehouse can enter the shipment reference and confirm dispatch.':'This order is complete.';});
 function advance(){if(order.stage==='Warehouse')form('Record invoice','advance',[{key:'invoice_number',label:'Invoice reference'}],'Mark invoiced');else if(order.stage==='Invoiced')form('Confirm dispatch','advance',[{key:'dispatch_reference',label:'Dispatch / shipment reference'}],'Mark dispatched');else direct('advance');}
 function output(){form('Record '+order.stage.toLowerCase()+' output','output',[{key:'good',label:'Good pieces',type:'number',min:0,value:0},{key:'rework',label:'Rework observations',type:'number',min:0,value:0,hint:'Observations, not additional completed pieces.'},{key:'note',label:'Shift / operator note',type:'textarea',required:false}]);}
 function inspection(){form('Add quality inspection','quality',[{key:'inspected',label:'Pieces inspected',type:'number',min:1,max:order.quantity},{key:'defects',label:'Pieces with defects',type:'number',min:0,value:0},{key:'result',label:'Result',type:'select',options:['Pass','Hold','Rework'].map(v=>({value:v,label:v}))},{key:'notes',label:'Inspection notes',type:'textarea',required:false}]);}
 function allocate(){
  const areas=(kind:string,current:string)=>(data.production_areas||[]).filter(a=>a.company_id===order.company_id&&a.kind===kind).map(a=>({value:a.name,label:a.name})).concat(current&&!(data.production_areas||[]).some(a=>a.company_id===order.company_id&&a.kind===kind&&a.name===current)?[{value:current,label:current}]:[]);
  form('Allocate production','allocate',[{key:'line_id',label:'Sewing line',type:'select',options:options(data.lines.filter(l=>l.company_id===order.company_id)),value:order.line_id},{key:'cutting_table',label:'Cutting table',type:'select',options:areas('cutting_table',order.cutting_table),value:order.cutting_table,required:false,hint:'Admin can register tables in User access.'},{key:'marker',label:'Marker',type:'select',options:['A','B','C'].map(v=>({value:v,label:'Marker '+v})),value:order.marker,required:false},{key:'sub_line',label:'Finishing sub-line',type:'select',options:areas('finishing_line',order.sub_line),value:order.sub_line,required:false,hint:'Admin can register finishing sub-lines in User access.'}]);
 }

 function workItem(){const kinds=[...(can('develop')&&order.stage==='Development'?['Style development','CAD / pattern']:[]),...(can('sample')&&order.stage==='Sampling'?['Proto sample','Fit sample','Pre-production sample']:[])];form('Add development record','work_item',[{key:'kind',label:'Record type',type:'select',options:kinds.map(v=>({value:v,label:v}))},{key:'title',label:'Title',value:order.style},{key:'status',label:'Status',type:'select',value:'Open',options:['Open','In progress','Approved','Changes needed'].map(v=>({value:v,label:v}))},{key:'notes',label:'Notes / revision',type:'textarea',required:false}]);}
 async function attach(){if(busy)return;const file=uploadInput.files?.[0];if(!file)return;busy=true;error='';try{await upload(order.id,file);details=await api(`/orders/${order.id}`);await onmutate();}catch(e){error=(e as Error).message;}finally{busy=false;uploadInput.value='';}}
 const related=(key:keyof Dataset)=>((data[key] as Row[])||[]).filter(x=>x.order_id===order.id);
</script>
<dialog bind:this={dialog} class="order-drawer" oncancel={e=>{if(busy)e.preventDefault();else onclose()}}>
 <header class="drawer-header"><div><p class="eyebrow">BUYER PURCHASE ORDER</p><h2>{order.po}</h2><p>{order.style}</p></div><button class="icon-button" aria-label="Close order" disabled={busy} onclick={onclose}><X size={21}/></button></header>
 <div class="order-summary"><Badge value={order.stage}/><Badge value={order.approval}/><span>{order.buyer}</span></div>
 <div class="drawer-tabs" role="tablist" aria-label="Order sections">{#each ['Overview','Production','Development','Materials','Documents'] as t}<button role="tab" aria-selected={tab===t} class:active={tab===t} onclick={()=>tab=t}>{t}</button>{/each}</div>
 <div class="drawer-body">
 {#if error}<p class="form-error" role="alert">{error}</p>{/if}
 <div class="workflow-path">{#each data.stages as stage,i}<span class:current={order.stage===stage} class:complete={i<data.stages.indexOf(order.stage)}>{stage==='Development'?'CAD':stage}</span>{/each}</div><div class="workflow-hint"><ArrowRight size={16}/><p>{workflowHint}</p></div>
 {#if tab==='Overview'}
  <div class="detail-grid"><div><span>Order quantity</span><strong>{fmt(order.quantity)} <small>pcs</small></strong></div><div><span>Ex-factory date</span><strong>{day(order.due_date)}</strong></div><div><span>Company</span><p>{order.company}</p></div><div><span>Buyer team</span><p>{order.team}</p></div><div><span>Sewing allocation</span><p>{order.line||'Not allocated'}</p></div><div><span>Finishing unit</span><p>{order.finishing_unit||'Pending approval'}{order.sub_line?' / '+order.sub_line:''}</p></div></div>
  {#if details.enquiry_id}<section class="drawer-section"><h3>Booking terms & consumption</h3>{#if details.booking_terms?.sale_type}<p>{details.booking_terms.sale_type} · {details.booking_terms.incoterm||'Incoterm not set'}{#if details.booking_terms.lut_number} · LUT {details.booking_terms.lut_number}{/if}</p>{/if}<div class="detail-grid"><div><span>Enquiry consumption / piece</span><strong>{Number(details.enquiry_consumption).toLocaleString('en-IN',{maximumFractionDigits:6})} m</strong></div><div><span>Production target / piece (5% lower)</span><strong>{Number(details.target_consumption).toLocaleString('en-IN',{maximumFractionDigits:6})} m</strong></div></div></section>{/if}
  {#if order.notes}<div class="note-box">{order.notes}</div>{/if}
  <section class="drawer-section"><div class="section-title"><h3><CalendarDays size={17}/> Time & action</h3>{#if can('plan')}<button class="text-button" onclick={()=>form('Add milestone','add_milestone',[{key:'title',label:'Milestone'},{key:'due_date',label:'Due date',type:'date'}])}><Plus size={15}/> Add</button>{/if}</div>
  {#each order.milestones||[] as m}<div class="milestone"><button class="check-button" class:checked={m.done} disabled={!can('plan')||busy} aria-label={(m.done?'Reopen ':'Complete ')+m.title} onclick={()=>direct('milestone',{milestone_id:m.id})}>{#if m.done}<Check size={13}/>{/if}</button><span class:done={m.done}>{m.title}</span><time>{day(m.due_date)}</time></div>{/each}</section>
  {#if order.invoice_number||order.dispatch_reference}<div class="note-box">{#if order.invoice_number}<p>Invoice: <strong>{order.invoice_number}</strong></p>{/if}{#if order.dispatch_reference}<p>Dispatch: <strong>{order.dispatch_reference}</strong></p>{/if}</div>{/if}
 {:else if tab==='Production'}
  <div class="section-title"><h3>Output by stage</h3>{#if can('quality')}<button class="text-button" onclick={inspection}><ShieldCheck size={16}/> Inspect</button>{/if}</div>
  {#each ['Cutting','Sewing','Finishing','Packing'] as s}<div class="stage-progress"><div><span>{s}</span><strong>{fmt(order.totals?.[s])} <small>/ {fmt(order.quantity)} pcs</small></strong></div><progress max={order.quantity} value={order.totals?.[s]||0}></progress></div>{/each}
  <section class="drawer-section"><h3>Quality checks</h3>{#each related('quality').toReversed() as q}<div class="record-line"><div><strong>{q.stage}</strong><small>{q.inspected} inspected · {q.defects} defects</small></div><Badge value={q.result}/></div>{:else}<p class="muted">No quality checks recorded.</p>{/each}</section>
  <section class="drawer-section"><h3>Output history</h3>{#each related('entries').toReversed() as e}<div class="record-line"><div><strong>{e.stage} · {fmt(e.good)} good pieces</strong><small>{e.note||'Output entry'} · {e.rework} rework observations</small></div><small>{day(e.created_at)}</small></div>{:else}<p class="muted">No output recorded.</p>{/each}</section>
 {:else if tab==='Development'}
  <div class="section-title"><h3>Style, CAD & samples</h3>{#if (can('develop')&&order.stage==='Development')||(can('sample')&&order.stage==='Sampling')}<button class="text-button" onclick={workItem}><Plus size={16}/> Add record</button>{/if}</div>
  {#each related('work_items') as item}<div class="work-card"><div><p class="eyebrow">{item.kind}</p><h3>{item.title}</h3><p>{item.notes||'No revision notes'}</p></div><Badge value={item.status}/>{#if can(item.kind.includes('sample')?'sample':'develop')&&order.stage===(item.kind.includes('sample')?'Sampling':'Development')}<button class="text-button" onclick={()=>onform({title:'Update '+item.kind,fields:[{key:'status',label:'Status',type:'select',value:item.status,options:['Open','In progress','Approved','Changes needed'].map(v=>({value:v,label:v}))},{key:'notes',label:'Revision / approval notes',type:'textarea',value:item.notes,required:false}],submit:async v=>{await api('/records/work_items/'+item.id,{action:'update',...v});await onmutate();}})}>Update record <ArrowRight size={14}/></button>{/if}</div>{:else}<p class="empty">No development records yet.</p>{/each}
 {:else if tab==='Materials'}
  <div class="section-title"><h3>Material requirements</h3>{#if can('plan')}<button class="text-button" onclick={()=>form('Add material requirement','material',[{key:'item_id',label:'Material',type:'select',options:options(data.inventory.filter(i=>i.company_id===order.company_id))},{key:'quantity',label:'Required quantity',type:'number',step:'0.01',min:0.01}])}><Plus size={16}/> Add material</button>{/if}</div>
  {#each details.materials||[] as m}<div class="record-line"><strong>{m.item}</strong><span>{fmt(m.quantity_hundredths/100)} {m.unit}</span></div>{:else}<p class="muted">No material requirements recorded.</p>{/each}
  <section class="drawer-section"><h3>Stock movements for this PO</h3>{#each details.movements||[] as m}<div class="record-line"><div><strong>{m.item}</strong><small>{m.reference}</small></div><span>{fmt(m.quantity_hundredths/100)} · {m.kind}</span></div>{:else}<p class="muted">No stock movements for this PO.</p>{/each}</section>
 {:else}
  <div class="section-title"><h3><Paperclip size={17}/> Order documents</h3>{#if can('documents')}<button class="button secondary small-button" disabled={busy} onclick={()=>uploadInput.click()}><Upload size={15}/>{busy?'Uploading…':'Upload file'}</button><input class="sr-only" bind:this={uploadInput} type="file" aria-label="Upload order document" onchange={attach}/>{/if}</div>
  <p class="muted">PO files, tech packs and CAD revisions. Maximum 20 MB per file.</p>
  {#each details.documents||[] as doc}<a class="document-row" href={'/api/documents/'+doc.id}><Paperclip size={18}/><div><strong>{doc.name}</strong><small>{fmt(doc.size/1024)} KB · {day(doc.created_at)}</small></div><Download size={16}/></a>{:else}<div class="empty"><Paperclip size={30}/><p>No documents attached to this order.</p></div>{/each}
 {/if}
 </div>
 <footer class="drawer-footer">
 {#if order.approval==='Pending'&&can('approve')}<button class="button secondary danger" disabled={busy} onclick={()=>direct('reject')}>Reject</button><button class="button primary" disabled={busy} onclick={()=>direct('approve')}><Check size={16}/> Approve PO</button>
 {:else}<div class="footer-secondary">{#if can('plan')&&data.stages.indexOf(order.stage)<=4}<button class="button secondary" onclick={allocate}>Allocate line</button>{/if}{#if ['Cutting','Sewing','Finishing','Packing'].includes(order.stage)&&can(stageGrant[order.stage])&&order.approval==='Approved'}<button class="button secondary" onclick={output}><Plus size={16}/> Record output</button>{/if}</div>{#if order.stage!=='Dispatched'&&can(stageGrant[order.stage])&&order.approval==='Approved'}<button class="button primary" disabled={busy} onclick={advance}>{order.stage==='Warehouse'?'Record invoice':order.stage==='Invoiced'?'Dispatch':order.stage==='Planning'?'Send to CAD':'Move to '+data.stages[data.stages.indexOf(order.stage)+1]}<ArrowRight size={16}/></button>{/if}{/if}
 </footer>
</dialog>
